type envelope struct {
	Kind string          `json:"kind"`   // tag travels with the payload
	Body json.RawMessage `json:"body"`
}

var e envelope
if err := json.Unmarshal(data, &e); err != nil {
	return nil, err
}
switch e.Kind {                                    // allow-list, not a class name
case "order.created":
	var v OrderCreated
	return v, json.Unmarshal(e.Body, &v)           // parse only after the tag resolved
case "order.cancelled":
	var v OrderCancelled
	return v, json.Unmarshal(e.Body, &v)
default:
	return nil, fmt.Errorf("unknown kind %q", e.Kind)   // fail closed
}
